-- Easy Beans (business 1): the Irish day's guest coffee is now Cocobrew's Oro Fino São Paulo, Brazil, from
-- the roaster's own shop (the link the owner sent still calls it Anhumas): from the Mogiana region of São
-- Paulo, grown at 800 to 1,100 m, balanced and sweet, with caramel, nuts and chocolate; roasted by hand
-- in micro-batches in Temple Bar, Dublin. The owner's pick is the 1 kg bag ground for French press
-- (€30.50; 250 g is €10.50). The coffee the Irish day serves takes its name, origin, roaster, tasting
-- notes, bag, link and the shop's photo of a Cocobrew bag, as the owner asked (what the café had on it is
-- replaced: the roast and process, which the shop doesn't give, are cleared); the Irish day's
-- description says so while it's still the one it started with. And Cocobrew on Suppliers, a coffee
-- roaster, or, when the café has added it already, its empty details filled in. Easy Beans is business 1
-- when it's named so or Aron is on its team; anywhere else nothing changes, and running it again changes
-- nothing.
do $$
declare
  v_name    constant text := 'Oro Fino São Paulo';
  v_link    constant text := 'https://www.cocobrew.ie/products/anhumas-sao-paulo-brazil?variant=42774084747423';
  v_notes   constant text := 'Speciality coffee roaster with a café in Temple Bar, Dublin: roasted by hand in micro-batches. '
                          || 'Oro Fino São Paulo (the Irish day coffee): 1 kg €30.50, 250 g €10.50, whole bean or ground '
                          || '(French press, AeroPress, espresso, moka pot, V60). Also tony@cocobrew.ie.';
  v_photo   constant text := 'data:image/jpeg;base64,';
  v_coffee uuid;
  v_sup    uuid;
begin
  if not exists (select 1 from public.business b
                  where b.id = 1
                    and (b.name ~* 'easy\s*beans'
                         or exists (select 1 from public.profiles p where p.business_id = 1 and p.full_name ~* '^\s*aron\M'))) then
    return;
  end if;
  -- Named, so the rules and the audit see Easy Beans (a migration runs signed out).
  perform set_config('app.business_id', '1', true);

  -- The coffee: this one if the café has added it already; else the one the Irish day serves; else the
  -- Irish guest blend by its name; else a new one.
  select c.id into v_coffee from public.coffees c
   where c.business_id = 1 and (c.name ~* 'oro\s*fino' or c.name ~* '\manhumas\M' or c.link ~* 'cocobrew\.ie/products/anhumas')
   order by c.active desc, c.sort limit 1;
  if v_coffee is null then
    select t.coffee_id into v_coffee from public.day_themes t
     where t.business_id = 1 and t.name ~* '\mirish\M' and t.coffee_id is not null order by t.sort limit 1;
  end if;
  if v_coffee is null then
    select c.id into v_coffee from public.coffees c where c.business_id = 1 and c.name ~* '\mirish\M' order by c.active desc, c.sort limit 1;
  end if;
  if v_coffee is null then
    insert into public.coffees (business_id, name, sort)
    values (1, v_name, coalesce((select max(sort) + 1 from public.coffees where business_id = 1), 1))
    returning id into v_coffee;
  end if;
  update public.coffees
     set name = v_name, country = 'BR', region = 'Mogiana, São Paulo (800–1,100 m)', roaster = 'Cocobrew', roast = null, process = null,
         tasting_notes = 'Caramel, nuts and chocolate: balanced and sweet', brew = 'filter', bag_grams = 1000, bag_price = 30.50,
         link = v_link, photo = v_photo, active = true
   where id = v_coffee;

  -- The Irish day serves it; its description follows while it's still the one it started with.
  update public.day_themes
     set coffee_id = v_coffee,
         description = case when description = 'The Irish guest blend, with Irish music to match.'
                            then 'Cocobrew’s Oro Fino, roasted in Dublin, with Irish music to match.' else description end
   where business_id = 1 and name ~* '\mirish\M';

  -- Suppliers: Cocobrew, a coffee roaster bought from now.
  select s.id into v_sup
    from public.suppliers s
   where s.business_id = 1 and (s.name ~* 'coco\s*brew' or s.email ~* '@cocobrew\.ie$' or s.website ~* 'cocobrew\.ie')
   order by s.active desc, s.created_at
   limit 1;
  if v_sup is null then
    insert into public.suppliers (business_id, name, kind, supplies, email, phone, website, order_url, address, active, notes)
    values (1, 'Cocobrew', 'Coffee roaster', array['coffee'], 'info@cocobrew.ie', '+353 87 932 1825', 'https://www.cocobrew.ie', v_link,
            'Temple Bar, Dublin, Ireland', true, v_notes);
  else
    update public.suppliers
       set kind = coalesce(kind, 'Coffee roaster'),
           supplies = case when 'coffee' = any(supplies) then supplies else supplies || array['coffee'] end,
           email = coalesce(email, 'info@cocobrew.ie'),
           phone = coalesce(phone, '+353 87 932 1825'),
           website = coalesce(website, 'https://www.cocobrew.ie'),
           order_url = coalesce(order_url, v_link),
           address = coalesce(address, 'Temple Bar, Dublin, Ireland'),
           active = true,
           notes = coalesce(notes, v_notes)
     where id = v_sup;
  end if;

  perform set_config('app.business_id', '', true);
end $$;
